    final Class<?> bm;
    final java.lang.reflect.Constructor<?> bmCtor;
    final Method bmSet;
    final java.lang.reflect.Constructor<?> ctor1; // (BitMatrix)
    final java.lang.reflect.Constructor<?> ctor4; // (BitMatrix,int,int,int)
    final Method detect;
    Api(ClassLoader cl) throws Exception {
      bm = Class.forName("com.google.zxing.common.BitMatrix", true, cl);
      bmCtor = bm.getConstructor(int.class, int.class);
      bmSet = bm.getMethod("set", int.class, int.class);
      Class<?> wr = Class.forName("com.google.zxing.common.detector.WhiteRectangleDetector", true, cl);
      ctor1 = wr.getConstructor(bm);
      ctor4 = wr.getConstructor(bm, int.class, int.class, int.class);
      detect = wr.getMethod("detect");
    }
    Object makeImage(boolean[][] on, int w, int h) throws Exception {
      Object m = bmCtor.newInstance(w, h);
      for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
          if (on[y][x]) {
            bmSet.invoke(m, x, y);
          }
        }
      }
      return m;
    }
    String run(boolean[][] on, int w, int h, int ctorKind, int initSize, int cx, int cy) {
