        Object pts = detect.invoke(det);
        int n = Array.getLength(pts);
        StringBuilder sb = new StringBuilder("OK|");
        for (int i = 0; i < n; i++) {
          Object p = Array.get(pts, i);
          sb.append(p.toString());
        }
        return sb.toString();
      } catch (Throwable t) {
        Throwable c = (t.getCause() != null) ? t.getCause() : t;
        return "EX|" + c.getClass().getName();
      }
    }
  }

  public static void main(String[] args) throws Exception {
    Api oldA = new Api(loader(args[0]));
    Api newA = new Api(loader(args[1]));
    Random r = new Random(314);

    long total = 0;
    long ok = 0;
    long mism = 0;

    int[] dims = { 10, 15, 21, 30, 45, 64, 90, 120 };
    for (int trial = 0; trial < 150000; trial++) {
      int w = dims[r.nextInt(dims.length)];
      int h = dims[r.nextInt(dims.length)];
      boolean[][] on = new boolean[h][w];
      int mode = r.nextInt(6);
      switch (mode) {
        case 0: // random
          for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
              on[y][x] = r.nextBoolean();
            }
          }
          break;
        case 1: break; // all white
        case 2: // filled black box in the middle (classic white-rectangle-with-content)
          for (int y = h / 4; y < 3 * h / 4; y++) {
            for (int x = w / 4; x < 3 * w / 4; x++) {
              on[y][x] = true;
            }
          }
          break;
        case 3: // black border frame
          for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
              on[y][x] = (x == 0 || y == 0 || x == w - 1 || y == h - 1);
            }
          }
          break;
        case 4: // sparse
          for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
              on[y][x] = r.nextInt(10) == 0;
            }
          }
          break;
        default: // diagonal / checker
          for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
              on[y][x] = (x + y) % 3 == 0;
            }
          }
          break;
      }
      int ctorKind = r.nextInt(2);
      int initSize = 2 + r.nextInt(Math.min(w, h));
      int cx = r.nextInt(w);
      int cy = r.nextInt(h);
      String a = oldA.run(on, w, h, ctorKind, initSize, cx, cy);
      String b = newA.run(on, w, h, ctorKind, initSize, cx, cy);
      total++;
      if (a.startsWith("OK")) {
        ok++;
      }
      if (!a.equals(b)) {
        mism++;
        if (mism <= 20) {
          System.out.println("MISMATCH w=" + w + " h=" + h + " mode=" + mode + " ctor=" + ctorKind +
              " initSize=" + initSize + " c=(" + cx + "," + cy + ")");
          System.out.println("  old: " + a);
          System.out.println("  new: " + b);
        }
      }
    }
    System.out.println("----");
    System.out.println("Total detect() calls:  " + total);
    System.out.println("Successful (OK):        " + ok);
    System.out.println("Mismatches:            " + mism);
    System.out.println(mism == 0 ? "RESULT: IDENTICAL BEHAVIOR" : "RESULT: DIFFERENCES FOUND");
  }
}

